<script>
document.addEventListener('DOMContentLoaded', function () {
    const useBonusCheckbox = document.querySelector('input[name="use_bonus"]');
    const bonusBalance = {{ Auth::user()?->bonus_balance ?? 0 }};
    const promoDiscount = {{ session('applied_discount.value') ?? 0 }};
    const promoType = '{{ session('applied_discount.type') ?? '' }}';
    const promoTarget = '{{ session('applied_discount.target_id') ?? '' }}';

    const totalPrice = {{ $total }};
    const discountAmount = {{ session('applied_discount.amount') ?? 0 }};
    const priceAfterPromo = totalPrice - discountAmount;
    const maxUsableBonus = Math.floor(priceAfterPromo * 0.5);
    const actualBonus = Math.min(bonusBalance, maxUsableBonus);
    const finalPrice = priceAfterPromo - actualBonus;

    document.querySelector('[data-promocode-value]').textContent = discountAmount + ' ₽';
    document.querySelector('[data-discount-value]').textContent = actualBonus + discountAmount + ' ₽';
    document.querySelector('.purchase__total-title').innerHTML = `Итого в моей корзине: ${finalPrice.toLocaleString('ru-RU')} ₽`;

    document.getElementById('priceInput').value = totalPrice;
    document.getElementById('finalPriceInput').value = finalPrice;
    document.getElementById('bonusInput').value = actualBonus;

    // Заблокировать чекбокс если бонусов 0
    if (bonusBalance <= 0) {
        useBonusCheckbox.disabled = true;
        useBonusCheckbox.closest('.form__item').style.opacity = 0.5;
    }

    useBonusCheckbox.addEventListener('change', () => {
        const applyBonus = useBonusCheckbox.checked;
        const newBonus = applyBonus ? actualBonus : 0;
        const newFinal = priceAfterPromo - newBonus;

        document.getElementById('bonusInput').value = newBonus;
        document.getElementById('finalPriceInput').value = newFinal;
        document.querySelector('[data-discount-value]').textContent = newBonus + discountAmount + ' ₽';
        document.querySelector('.purchase__total-title').innerHTML = `Итого в моей корзине: ${newFinal.toLocaleString('ru-RU')} ₽`;
    });
});

</script>


